mapper.select:
SELECT rc.CLASS_IDX, NVL(ROUND(AVG(rc.RATING), 1), 0) AS AVG_RATING, NVL(COUNT(*), 0) AS REVIEW_COUNT FROM REVIEW_CLASS rc WHERE rc.CLASS_IDX IN
#{id}
GROUP BY rc.CLASS_IDX

mapper.update:
UPDATE USERS
SET STATUS = #{status}
WHERE USER_IDX = #{userIdx}

mapper.select:
SELECT COUNT(*)
FROM CERT
WHERE USER_IDX = #{userIdx}
AND CERT_TYPE = #{certType}
